//! Builds the runtime of compiled programs, the library written in Koji (std/koji/), as a static
//! library that `kojic build` links into every program: its C, generated by kojic
//! (bootstrap/libkoji.c.gz), compiled and archived. Its path is given to the tests as
//! `KOJI_RUNTIME_LIB`. The prelude of the generated C (`runtime/prelude.h`) is in the compiler.

use std::env;
use std::path::PathBuf;
use std::process::Command;

fn main() {
    println!("cargo:rerun-if-changed=bootstrap/libkoji.c.gz");
    let out_dir = PathBuf::from(env::var("OUT_DIR").expect("OUT_DIR"));
    let source = out_dir.join("libkoji.c");
    let unpacked = Command::new("gzip").args(["-dc", "bootstrap/libkoji.c.gz"]).output().expect("cannot run gzip");
    assert!(unpacked.status.success(), "cannot unpack bootstrap/libkoji.c.gz");
    std::fs::write(&source, unpacked.stdout).expect("cannot write libkoji.c");
    let object = out_dir.join("libkoji.o");
    let cc = env::var("KOJI_CC").unwrap_or_else(|_| "cc".to_string());
    let compiled = Command::new(&cc).args(["-O2", "-c", "-o"]).arg(&object).arg(&source).status().expect("cannot run the C compiler");
    assert!(compiled.success(), "compiling the library written in Koji failed");
    let library = out_dir.join("libkoji_runtime.a");
    // A new archive each time (`ar` adds to an existing one).
    let _ = std::fs::remove_file(&library);
    let archived = Command::new("ar").arg("rcs").arg(&library).arg(&object).status().expect("cannot run ar");
    assert!(archived.success(), "archiving the runtime failed");
    println!("cargo:rustc-env=KOJI_RUNTIME_LIB={}", library.display());
}
